head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.gExplDisclsAcptNo;
scwin.gExplDisclsOrdNo;
scwin.gIsurCd;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gParamObj = new Array(1);
scwin.vScrenID = 'ULDSTF30223.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_resizeToWin = function() {
    frame.Width = 670;
    frame.Height = 270;
};
scwin.fn_GetProvider = function() {
    var url = frame.srcUrl;
    var arr = url.split("?")[1];
    return (arr.length >= 1 ? arr : undefined);

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !정보--;
셋팅-- > function() {
    scwin.gEmpNo = js_emp_no; // 세션정보 

    scwin.gExplDisclsAcptNo = $c.frame.path("../").txb_acpt_no.getValue();
    scwin.gExplDisclsOrdNo = $c.frame.path("../").scwin.gExplDisclsOrdNo;
    scwin.gIsurCd = $c.frame.path("../").txb_isur_cd.getValue();
    //alert("gIsurCd--> : " + gIsurCd);

    txb_com_abbrv.setValue($c.frame.path("../").txb_com_abbrv.getValue());
    txb_emp_nm.setValue(js_emp_nm);
    $c.stf.setObjectValue(txb_re_acptno, scwin.gExplDisclsAcptNo);
};
scwin.fn_Insert = function() {
    var vAcptNo = $c.stf.getObjectValue(txb_acptno);
    if (vAcptNo.length != 14) {
        $c.win.alert("공시를 선택하세요.");
        return;
    }
    if ($c.stf.getObjectValue(txa_remk).length > 200) {
        $c.win.alert("비고는  200자이하만 입력할 수 있습니다.");
        return false;
    }
    dts_explanation_new.insertRow();
    dts_explanation_new.setCellData(1, "REDISCLS_ACPT_NO", scwin.gExplDisclsAcptNo);
    dts_explanation_new.setCellData(1, "EXPLDISCLS_ACPT_NO", $c.stf.getObjectValue(txb_acptno));
    dts_explanation_new.setCellData(1, "REG_ID", scwin.gEmpNo);
    dts_explanation_new.setCellData(1, "REMK", $c.stf.getObjectValue(txa_remk));


    //alert("gExplDisclsAcptNo -->> : " +gExplDisclsAcptNo);
    //alert("getObjectValue(txb_acptno) -->> : " +getObjectValue(txb_acptno));

    var vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer == true) {
        trs_explanation_new.Action = "/ExplanationDisclosure.do?method=registerExplanationReDscl&inputMessageId=EXPLDISCLSREAD_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_explanation_new.KeyName = "toinb_dataid4";
        trs_explanation_new.KeyValue = "JSP(I:pInput=dts_explanation_new)";
        trs_explanation_new.Post();
    }
};
scwin.img_search_onclick = async function() {
    var winTitle = txb_com_abbrv.getValue() + " / 공시 제출현황";
    //var url = "/dsclmgt/ULDSTF30224.gfm";
    //rame.CreateFrame("DSCLLIST"+gIsurCd, url , winTitle, 70, 10, 630, 330+30, "window" , 0, 0, true);	
    await $c.frame.CreateDialogFrame("EXPL_LIST", "/dsclmgt/ULDSTF30224.gfm", winTitle, 100, 100, 700, 500, "window");
};
scwin.trs_explanation_new_OnSuccess = async function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    await $c.frame.CloseFrame();
    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_reload();
};
scwin.trs_explanation_new_OnFail = function() {
    $c.win.alert('trs_explanation_new.OnFail() :' + trs_explanation_new.ErrorMsg);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Insert();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_resizeToWin();
    //hidden 추가 (ysh)
    $c.stf.showObj(txb_re_acptno, false);
    $c.stf.showObj(txb_acptno, false);
    fn_GetParentValue();

    // 가우스헤더 셋팅
    dts_explanation_new.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=EXPLDISCLSREAD_INOUT";
    dts_explanation_new.reset();
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
};
